const LESSONS=[];
function lesson(c,title,why,example,steps,q,options,answer,feedback,sources,lab){LESSONS.push({id:LESSONS.length,c,title,why,example,steps,q,options,answer,feedback,sources,lab,minutes:6+steps.length});}
const P=(ur,en)=>[ur,en];
lesson(0,P('Google Ads ki 7 main types','The 7 main campaign types'),P('Campaign type decide karti hai ad kahan aur kis tarah deliver ho sakta hai. Search, Display, Shopping, Video, App, Demand Gen aur Performance Max ko pehchano. Is course ka focus Search hai.','Campaign type shapes where and how ads can serve. Recognize Search, Display, Shopping, Video, App, Demand Gen and Performance Max. This course focuses on Search.'),P('Search mein customer khud kuch dhoond raha hota hai. Hum us search ke waqt relevant offer dete hain.','In Search, the customer is actively looking for something. We show a relevant offer at that moment.'),[P('Campaign gallery mein har type ka example dekho.','Explore an example of each campaign type.'),P('Apne business ka main goal likho: sale, lead ya awareness.','Write your business goal: a sale, a lead or awareness.')],P('Search campaign ki khas baat kya hai?','What makes Search distinctive?'),[P('Customer ki search se match hona','Matching a customer search'),P('Sirf mobile apps par chalna','Only running inside mobile apps'),P('Har click par sale ki guarantee','Guaranteeing a sale with every click')],0,P('Search intent capture karta hai. Click milna sale ki guarantee nahi.','Search captures intent. A click does not guarantee a sale.'),['types'],'types');
lesson(0,P('Search ka safar: query se customer','From query to customer'),P('Search term user ke actual words hain. Keyword advertiser ka targeting input hai. Ad se click, landing page se action aur sales process se customer milta hai.','A search term is what someone actually searches. A keyword is the advertiser’s targeting input. The ad earns a click; the page earns an action; the sales process earns a customer.'),P('“AC repair Lahore” service lenay ka signal hai; “AC repair jobs” naukri ka. Dono mein AC repair hai, lekin zarurat alag hai.','“AC repair Lahore” suggests service intent; “AC repair jobs” suggests employment intent. Similar words, different needs.'),[P('Search lab mein terms ko Keep, Block ya Investigate karo.','Classify searches as Keep, Block or Investigate in the lab.'),P('Har term par poochho: kya hum iska solution bechtay hain?','For each term, ask: do we sell the solution this person needs?')],P('Keyword aur search term ek hi cheez hain?','Are keywords and search terms identical?'),[P('Haan, hamesha','Yes, always'),P('Nahi; input aur actual query alag hain','No; targeting input and actual query differ')],1,P('Reports mein actual queries dekho. Keyword ka naam akela intent nahi batata.','Read actual queries in reports. The keyword alone does not tell the full story.'),['terms'],'keywords');
lesson(0,P('Auction aur Ad Rank','The auction and Ad Rank'),P('Sabse zyada bid denay wala hamesha nahi jeetta. Bid, ad aur page ki quality, context, competition, thresholds aur assets ka expected impact auction mein matter karta hai.','The highest bid does not always win. Bids, ad and page quality, context, competition, thresholds and expected asset impact all matter.'),P('Relevant repair ad aur useful repair page, generic homepage se behtar customer experience de saktay hain.','A relevant repair ad and helpful repair page can create a better experience than a generic homepage.'),[P('Ad aur landing page mein same service rakho.','Align the service in the ad and landing page.'),P('Quality Score ko diagnosis samjho; bid × score ko exact live formula mat samjho.','Use Quality Score for diagnosis; do not treat bid × score as the live auction formula.')],P('Quality Score kya hai?','What is Quality Score?'),[P('Guaranteed ranking formula','A guaranteed ranking formula'),P('Keyword-level diagnostic signal','A keyword-level diagnostic tool')],1,P('Quality Score 1–10 diagnostic hai, direct auction input nahi.','Quality Score is a 1–10 diagnostic, not a direct auction input.'),['rank','quality']);
lesson(1,P('Customer, offer aur intent','Customer, offer and intent'),P('Pehle decide karo kis customer ko kis problem ka kya solution dogay. Sirf “best service” kehna kaafi nahi; location, availability aur sachay benefits clear karo.','Decide whose problem you solve and what you offer. “Best service” is vague; make location, availability and truthful benefits clear.'),P('Emergency repair aur annual maintenance alag needs hain; inki messaging aur pages alag ho sakti hain.','Emergency repair and annual maintenance are different needs; they may need different messages and pages.'),[P('Customer ki problem ek sentence mein likho.','Describe the customer problem in one sentence.'),P('Ek real benefit aur clear next step choose karo.','Choose a real benefit and a clear next step.')],P('“Guaranteed #1 service” bina evidence ke likhna?','Should you claim “Guaranteed #1 service” without evidence?'),[P('Nahi; sachay benefits likho','No; use truthful benefits'),P('Haan, clicks barhenge','Yes, it may attract clicks')],0,P('Ad ka promise deliver hona chahiye. Invented claims trust aur policy problems la saktay hain.','The promise must be deliverable. Invented claims create trust and policy problems.'),['creative'],'ad');
lesson(1,P('Landing page aur sales funnel','Landing page and sales funnel'),P('User ko relevant page chahiye: same offer, clear price ya quote process, proof, fast mobile experience aur simple contact form. Slow sales follow-up bhi result kharab kar sakta hai.','Visitors need a relevant page: the same offer, clear pricing or quote process, evidence, a fast mobile experience and an easy next step. Slow sales follow-up can also hurt results.'),P('Repair ad se generic blog par bhejna extra friction hai. Repair page par service area aur booking clear ho.','Sending repair traffic to a generic blog adds friction. A repair page should explain coverage and booking.'),[P('Mobile par page kholo aur booking khud complete karo.','Open the page on mobile and complete the booking yourself.'),P('Form error, phone button aur thank-you state check karo.','Check form errors, the call button and the success state.')],P('Clicks hain lekin forms nahi: pehla useful check?','Clicks but no forms: what is a useful first check?'),[P('Budget double karo','Double the budget'),P('Tracking aur landing page test karo','Test tracking and the landing page')],1,P('Pehle measurement aur experience validate karo, phir traffic aur offer diagnose karo.','Validate measurement and experience before diagnosing traffic and the offer.'),['creative','quality']);
lesson(1,P('Kitna paisa afford kar saktay ho?','What can you afford to pay?'),P('Revenue poora profit nahi. Product, delivery, payment, returns aur service costs ke baad jo contribution bachta hai us se acquisition cost judge karo.','Revenue is not profit. Judge acquisition cost against contribution after product, delivery, payment, return and service costs.'),P('Rs 8,000 sale par 40% contribution = Rs 3,200 before ads. Agar har 4 leads se 1 sale ho to break-even CPL = Rs 800, overhead se pehle.','An Rs 8,000 sale at 40% contribution leaves Rs 3,200 before ads. At 1 sale per 4 leads, break-even CPL is Rs 800 before overhead.'),[P('Calculator mein revenue, contribution margin aur close rate dalo.','Enter revenue, contribution margin and close rate in the calculator.'),P('Break-even se neeche profit buffer rakho.','Leave a profit buffer below break-even.')],P('Rs 3,200 contribution aur 25% close rate: break-even CPL?','Rs 3,200 contribution and 25% close rate: break-even CPL?'),[P('Rs 3,200','Rs 3,200'),P('Rs 800','Rs 800'),P('Rs 12,800','Rs 12,800')],1,P('3,200 × 0.25 = 800. Ye assumptions par based ceiling hai, profit target nahi.','3,200 × 0.25 = 800. This is an assumption-based ceiling, not a profit target.'),[],'calculator');
lesson(2,P('Conversion ka sahi goal','Choose the right conversion'),P('Conversion business ke liye meaningful action hai. Primary action selected campaign goal ke saath bidding mein use ho sakta hai; secondary aam tor par observation ke liye hai. Custom goals mein secondary bhi bidding mein use ho sakta hai.','A conversion is a meaningful business action. A primary action can guide bidding when its goal is selected; secondary actions usually serve observation. A secondary action in a custom goal can also guide bidding.'),P('Contact page view aur qualified booking equal nahi. Dono count karne se “Conversions” inflated lag sakti hain.','A contact-page view is not equal to a qualified booking. Counting both can make results look inflated.'),[P('Main outcome select karo: purchase ya qualified lead.','Choose the main outcome: a purchase or qualified lead.'),P('Har campaign ke selected goals aur primary actions review karo.','Review selected goals and primary actions for each campaign.')],P('Lead form aur page view ko equal optimize karna?','Should a lead form and a page view carry equal optimization priority?'),[P('Haan, har action same hai','Yes, every action is equal'),P('Nahi; business value dekho','No; consider business value')],1,P('Useful outcomes select karo. Sirf primary label kaafi nahi; selected campaign goal bhi matter karta hai.','Select useful outcomes. The primary label alone is not enough; campaign goals also matter.'),['goals','tracking']);
lesson(2,P('Google tag, GTM aur GA4','Google tag, GTM and GA4'),P('Tag measurement bhejta hai, GTM tags manage karta hai, GA4 behavior analyze karta hai. Implementation route choose karo aur same outcome ko multiple primary sources se duplicate mat count karo.','Tags send measurement; GTM manages tags; GA4 analyzes behavior. Choose an implementation route and avoid counting the same outcome through duplicate primary sources.'),P('Google Ads tag aur GA4 import dono same purchase count karein to ek order do primary conversions ban sakta hai.','If a Google Ads tag and a GA4 import both count the same purchase, one order may become two primary conversions.'),[P('Success event par trigger lagao, sirf button click par nahi jab outcome form submission ho.','Trigger on success, not just the click when the intended outcome is form completion.'),P('Tag Assistant/Preview mein test karo; refresh aur repeat submit bhi check karo.','Test with Tag Assistant/Preview, including refresh and repeat submission.'),P('Purchase value, currency aur unique transaction ID validate karo.','Validate purchase value, currency and unique transaction ID.')],P('Ek order do dafa primary count ho raha hai. Kya karo?','One order is counted twice as primary. What next?'),[P('Source aur deduplication investigate karo','Investigate sources and deduplication'),P('Achha result samajh kar chhor do','Accept it as better performance')],0,P('Ad platform, analytics aur backend order IDs reconcile karo.','Reconcile the ad platform, analytics and backend order IDs.'),['tracking','goals']);
lesson(2,P('Lead quality, consent aur offline sales','Lead quality, consent and offline sales'),P('Form aana sale nahi. CRM mein qualified lead aur closed sale ka feedback rakho. Enhanced conversions first-party data se measurement improve kar sakti hain; consent, customer-data terms aur data handling implement karo.','A form is not a sale. Track qualified leads and closed sales in the CRM. Enhanced conversions can improve measurement with first-party data; implement consent, customer-data terms and appropriate handling.'),P('20 leads mein sirf 2 relevant hon to cheap CPL misleading hai. Qualified lead ka cost aur actual sales dekho.','If only 2 of 20 leads are relevant, a low CPL can mislead. Examine qualified-lead cost and sales.'),[P('CRM mein lead ID, qualification aur close date store karo.','Store lead ID, qualification and close date in the CRM.'),P('Data Manager ke current supported import route aur diagnostics check karo.','Check current supported Data Manager import routes and diagnostics.'),P('Phone clicks ko answered/qualified calls se alag samjho; country availability check karo.','Distinguish phone clicks from answered/qualified calls; check country availability.')],P('Cheap leads lekin koi customer nahi. Best next check?','Cheap leads but no customers. What should you inspect?'),[P('Sirf CTR','Only CTR'),P('Lead quality aur sales follow-up','Lead quality and sales follow-up')],1,P('Business outcome tak feedback loop banao; fake ya duplicate conversions ko fix karo.','Build a feedback loop through to business outcomes; fix fake and duplicate conversions.'),['enhanced','offline']);
lesson(3,P('Keyword research: customer ki zubaan','Research in your customer’s language'),P('Seed services, customer problems, locations aur product categories se shuru karo. Keyword Planner ke ideas aur forecasts ko estimate samjho; competitors ki copy ko proof nahi.','Start with services, problems, locations and product categories. Treat Keyword Planner ideas and forecasts as estimates; competitor copy is not evidence of success.'),P('Repair, installation aur maintenance ko ek hi ad mein bharne ke bajaye related intent groups banao.','Group repair, installation and maintenance by intent rather than cramming them into one generic message.'),[P('Business ke liye 5 seed phrases likho.','Write five seed phrases for the business.'),P('Informational, commercial aur irrelevant intent mark karo.','Label informational, commercial and irrelevant intent.'),P('Expected CPC aur local demand ko forecast ke saath compare karo.','Compare expected CPC and local demand with forecasts.')],P('High search volume ka matlab profitable keyword?','Does high search volume guarantee profitability?'),[P('Nahi; intent aur economics bhi matter karte hain','No; intent and economics also matter'),P('Haan, hamesha','Yes, always')],0,P('Useful demand chahiye, sirf zyada searches nahi.','You need useful demand, not just a large search count.'),['match','setup'],'keywords');
lesson(3,P('Exact, phrase aur broad match','Exact, phrase and broad match'),P('Exact same meaning/intent tak match kar sakta hai; sirf exact letters nahi. Phrase meaning include karta hai; broad related searches tak ja sakta hai aur extra signals use karta hai.','Exact can match the same meaning or intent, not only identical letters. Phrase includes the meaning; broad can reach related searches and use additional signals.'),P('[AC repair] exact hai, "AC repair" phrase hai aur AC repair broad hai. Match type reach ko steer karta hai; actual queries review karna phir bhi zaroori hai.','[AC repair] is exact, "AC repair" is phrase and AC repair is broad. Match types steer reach; actual query review still matters.'),[P('Teen syntaxes likho aur reach ka farq explain karo.','Write the three syntaxes and explain reach.'),P('Broad test se pehle valid conversion tracking aur Smart Bidding strategy assess karo.','Assess valid conversion tracking and Smart Bidding before testing broad.')],P('Exact match ka matlab sirf same spelling?','Does exact match mean identical spelling only?'),[P('Haan','Yes'),P('Nahi, same meaning/intent bhi','No, the same meaning or intent can qualify')],1,P('Modern matching meaning samajhta hai. Close variants ko ignore mat karo.','Modern matching considers meaning. Do not ignore close variants.'),['match'],'keywords');
lesson(3,P('Negative keywords aur search terms','Negatives and search terms'),P('Negative terms unwanted searches exclude karte hain. Negative broad, phrase aur exact ke rules positive matching se alag hain; synonyms aur singular/plural coverage khud check karo.','Negative terms exclude unwanted searches. Negative broad, phrase and exact follow different rules from positive matching; check synonyms and singular/plural coverage.'),P('Repair service ke liye jobs block karna sensible ho sakta hai. Lekin “cheap” ko har business mein block karna universal rule nahi.','Blocking jobs may fit a repair business. Blocking “cheap” is not a universal rule for every business.'),[P('Search-term lab mein har row ko classify karo.','Classify every row in the search-term lab.'),P('Account, campaign aur ad-group level par list ki scope check karo.','Check list scope at account, campaign and ad-group levels.'),P('Relevant queries galti se block to nahi hui? Conflicts check karo.','Check whether a negative accidentally blocks useful queries.')],P('Negative keyword add karte waqt kya zaroor check karo?','What must you check when adding a negative?'),[P('Scope, match type aur useful traffic par asar','Scope, match type and impact on useful traffic'),P('Sirf keyword ki length','Only its length')],0,P('Exclusion precise rakho; query relevance aur business context pehle dekho.','Keep exclusions precise; inspect query relevance and business context first.'),['negative','terms'],'keywords');
lesson(4,P('Account → campaign → ad group','Account → campaign → ad group'),P('Account mein billing/access, campaign mein budget aur major settings, ad group mein related keywords aur ads hotay hain. Structure ko business control aur useful reporting ke mutabiq rakho.','Accounts hold billing/access, campaigns hold budgets and major settings, and ad groups contain related keywords and ads. Structure around useful business controls and reporting.'),P('Different cities ke separate budgets hon to campaigns alag ho sakti hain. Similar intent ke words ek focused ad group mein reh saktay hain.','Separate city budgets may justify separate campaigns. Similar-intent keywords can share a focused ad group.'),[P('Ek campaign aur do intent-based ad groups sketch karo.','Sketch a campaign with two intent-based ad groups.'),P('Brand aur non-brand reporting ki need decide karo.','Decide how you will report brand versus non-brand.')],P('Har keyword ki alag campaign lazmi hai?','Does every keyword require its own campaign?'),[P('Haan','Yes'),P('Nahi, business controls aur intent dekho','No, consider business controls and intent')],1,P('Unnecessary fragmentation management aur learning ko mushkil bana sakti hai.','Unnecessary fragmentation can complicate management and learning.'),['setup'],'campaign');
lesson(4,P('Location, language aur network settings','Location, language and networks'),P('Location setting physical presence aur location interest mein farq kar sakti hai. Apni service coverage ke mutabiq option choose karo. Language targeting interface translation nahi; user ki samajh ke signals bhi matter karte hain.','Location options can distinguish presence from location interest. Choose based on service coverage. Language targeting is not interface translation; language-understanding signals can matter.'),P('Sirf Lahore service ho to out-of-area enquiries ka reason location options aur actual user-location report mein dhoondo.','For a Lahore-only service, investigate location options and user-location reports when enquiries come from elsewhere.'),[P('Included aur excluded areas document karo.','Document included and excluded areas.'),P('Search partners aur doosray network options separately review karo.','Review Search partners and other network options separately.'),P('Ad language, landing page aur support team ki language match karo.','Align ad language, landing-page language and support capability.')],P('Lahore-only service ke liye best approach?','What suits a Lahore-only service?'),[P('Coverage ke mutabiq location options aur report verify karo','Verify location options and reports against coverage'),P('Puri duniya target karo','Target the whole world')],0,P('Location targeting perfect GPS boundary nahi; reports aur lead feedback review karo.','Location targeting is not a perfect GPS boundary; review reports and lead feedback.'),['setup']);
lesson(4,P('Schedule, devices aur audiences','Schedules, devices and audiences'),P('Schedule sales capacity ke mutabiq rakho. Audience Observation aur Targeting alag hain: Observation aam tor par reach narrow nahi karta; Targeting karta hai. Smart Bidding mein manual adjustments ka support strategy-specific hota hai.','Schedule around service capacity. Observation and Targeting differ: Observation generally does not narrow reach; Targeting does. Manual adjustment support depends on the bidding strategy.'),P('Agar phone raat ko koi nahi uthata to call-focused messaging aur schedule ka plan banao; forms phir bhi accept ho saktay hain.','If nobody answers calls at night, plan call messaging and schedules; forms may still be accepted.'),[P('Working hours aur timezone record karo.','Record working hours and account timezone.'),P('Mobile page aur form test karo.','Test the mobile page and form.'),P('Audience mode aur privacy/eligibility restrictions check karo.','Check audience mode and privacy/eligibility restrictions.')],P('Audience observation ka maqsad?','What is audience observation mainly for?'),[P('Har non-member ko exclude karna','Excluding every non-member'),P('Audience performance observe karna','Observing audience performance')],1,P('Reach limit karne se pehle Observation aur Targeting ka farq check karo.','Check Observation versus Targeting before restricting reach.'),['setup'],'campaign');
lesson(5,P('Responsive Search Ad likho','Write a responsive Search ad'),P('RSA multiple headlines aur descriptions ko combinations mein assemble karta hai. Relevant offer, real benefit aur clear action likho. Har possible combination meaningful hona chahiye.','An RSA assembles combinations of headlines and descriptions. Write a relevant offer, truthful benefit and clear action. Each possible combination should make sense.'),P('“AC Repair in Lahore” + “Request an Appointment” clear hai. “Best Best Best!!!” useful information nahi deta.','“AC Repair in Lahore” + “Request an Appointment” is clear. “Best Best Best!!!” adds little information.'),[P('Ad lab mein 3 headlines aur 2 descriptions likho.','Write three headlines and two descriptions in the ad lab.'),P('Har headline 30 aur description 90 characters ke andar rakho.','Keep each headline within 30 and each description within 90 characters.'),P('Full RSA ke liye unique assets add karo; preview serving guarantee nahi.','Expand unique assets for a full RSA; preview does not guarantee serving.')],P('Kya har entered headline har impression par show hoti hai?','Does every entered headline show on every impression?'),[P('Nahi; combinations aur available space vary karte hain','No; combinations and available space vary'),P('Haan','Yes')],0,P('RSA mein minimum 3 headlines aur 2 descriptions, maximum 15 aur 4 hain. Har combination ko review karo.','An RSA supports 3–15 headlines and 2–4 descriptions. Review possible combinations.'),['rsa'],'ad');
lesson(5,P('Assets aur ad relevance','Assets and ad relevance'),P('Sitelinks useful pages tak le jatay hain; callouts benefits, structured snippets categories aur call/location assets relevant contact information dete hain. Har asset har dafa show nahi hota.','Sitelinks lead to useful pages; callouts highlight benefits; structured snippets list categories; call/location assets add relevant contact information. Assets do not show every time.'),P('Services, Pricing aur Contact ke sitelinks tab use karo jab pages real aur useful hon. Fake pages ya unsupported offers mat add karo.','Use Services, Pricing and Contact sitelinks when the pages are real and useful. Do not invent destinations or unsupported offers.'),[P('Teen useful destination pages select karo.','Select three useful destination pages.'),P('Pinning sirf business/legal requirement par soch samajh kar use karo.','Use pinning thoughtfully when business or legal requirements justify it.'),P('Asset-level results ko context mein dekho; Ad Strength ko profit score na samjho.','Interpret asset results in context; Ad Strength is not a profit score.')],P('Ad Strength excellent hai: profit guaranteed?','Excellent Ad Strength: is profit guaranteed?'),[P('Haan','Yes'),P('Nahi, outcomes aur costs dekho','No, inspect outcomes and costs')],1,P('Creative guidance helpful hai; business performance alag measure hoti hai.','Creative guidance helps, but business performance is measured separately.'),['creative'],'ad');
lesson(5,P('Policies, approvals aur landing-page trust','Policies, approvals and page trust'),P('Ad, assets, business claims aur destination policy review mein aatay hain. Misleading claims, broken links aur restricted categories delivery ko rok saktay hain. Apni industry aur country ki policy verify karo.','Ads, assets, claims and destinations undergo policy review. Misleading claims, broken links and restricted categories can prevent delivery. Verify policies for your industry and country.'),P('Ad mein free visit likha hai lekin page par compulsory fee hai: promise aur actual offer mismatch hai.','An ad promises a free visit but the page requires a fee: the offer is inconsistent.'),[P('Offer, price, terms aur contact details cross-check karo.','Cross-check offers, pricing, terms and contact details.'),P('Disapproval ka exact reason parho aur root cause fix karo.','Read the exact disapproval reason and fix its cause.'),P('Fix ke baad supported review/appeal route use karo; bypass account mat banao.','After fixing it, use supported review/appeal routes rather than bypass accounts.')],P('Ad disapproved ho to pehla step?','First step after disapproval?'),[P('Exact policy reason aur destination inspect karo','Inspect the exact policy reason and destination'),P('Same ad multiple accounts mein chalao','Run the same ad across new accounts')],0,P('Root cause fix karo aur genuine review process follow karo.','Fix the cause and follow the legitimate review process.'),['rsa','setup']);
lesson(6,P('Daily budget aur monthly exposure','Daily budget and monthly exposure'),P('Average daily budget har din ka hard cap nahi. Most campaigns mein daily spend 2× tak aur unchanged full-month budget ka monthly limit aam tor par 30.4× hota hai. Budget changes aur exceptions ka rule check karo.','An average daily budget is not a daily hard cap. Most campaigns can spend up to 2× daily, with a usual full-month limit of 30.4× an unchanged daily budget. Check exceptions and budget-change rules.'),P('Rs 1,000/day ka illustrative full-month limit Rs 30,400 hai; ek din Rs 2,000 tak spend ho sakta hai.','Rs 1,000/day implies an illustrative full-month limit of Rs 30,400; a day may spend up to Rs 2,000.'),[P('Calculator mein affordable monthly amount se daily budget nikalo.','Use the calculator to convert an affordable monthly amount to a daily budget.'),P('Taxes/fees aur billing method alag check karo.','Check taxes/fees and billing method separately.')],P('Rs 1,000 average daily budget = har din maximum Rs 1,000?','Does a Rs 1,000 average daily budget cap each day at Rs 1,000?'),[P('Haan','Yes'),P('Nahi','No')],1,P('Average budget ko cash-flow planning ke saath samjho.','Understand average budgets when planning cash flow.'),['budget'],'calculator');
lesson(6,P('Bidding: objective pehle, strategy baad','Bidding follows the objective'),P('Manual CPC clicks ki bid control deta hai; Maximize clicks traffic par focus karta hai. Smart Bidding conversions ya value optimize karta hai: Maximize conversions, Target CPA, Maximize conversion value aur Target ROAS.','Manual CPC controls click bids; Maximize clicks focuses on traffic. Smart Bidding optimizes conversions or value: Maximize conversions, Target CPA, Maximize conversion value and Target ROAS.'),P('June 2026 se target wali strategies ke labels simplify ho rahay hain. Account mein old ya new label mil sakta hai; behavior ko samjho.','From June 2026, target strategy labels are being simplified. Accounts may show old or new names; understand the behavior.'),[P('Goal ko traffic, conversion count ya value mein classify karo.','Classify your goal as traffic, conversion count or value.'),P('Conversion/value data validate karke strategy choose karo.','Validate conversion/value data before choosing a strategy.')],P('Different order values hon to kis cheez ko consider karo?','If order values vary, what should you consider?'),[P('Reliable values ke saath value-based bidding','Value-based bidding with reliable values'),P('Sirf cheapest clicks','Only the cheapest clicks')],0,P('Value-based bidding ko sahi values chahiye; fake values optimization ko mislead karti hain.','Value-based bidding needs accurate values; fabricated values mislead optimization.'),['bid'],'campaign');
lesson(6,P('Targets aur learning ko samjho','Targets and learning'),P('Target CPA/ROAS guarantee nahi; auction aur conversion mix se actual result vary karta hai. Bohat restrictive target delivery limit kar sakta hai. Universal “itni conversions ke baad switch” rule mat lagao.','CPA/ROAS targets are not guarantees. Auction conditions and conversion mix affect outcomes. Restrictive targets can limit delivery. Avoid universal conversion-count switching rules.'),P('Historical CPA Rs 2,000 hai; seedha Rs 200 target rakhna magical efficiency nahi deta.','If historical CPA is Rs 2,000, setting Rs 200 does not magically create efficiency.'),[P('Recent mature data aur business economics compare karo.','Compare recent mature data with business economics.'),P('Changes document karo aur conversion delay ke mutabiq evaluate karo.','Document changes and evaluate against conversion delay.'),P('Budget, goal aur target sab ek saath change na karo jab impact isolate karna ho.','Avoid changing budget, goals and targets together when isolating impact.')],P('Target CPA hit na ho to foran har din change karna?','Should you change targets every day if CPA is missed?'),[P('Nahi; tracking, data maturity aur constraints diagnose karo','No; diagnose tracking, data maturity and constraints'),P('Haan, daily random target try karo','Yes, try random targets daily')],0,P('Learning aur conversion lag ko waqt do; serious errors ko phir bhi foran fix karo.','Allow for learning and conversion lag while fixing serious errors promptly.'),['bid','window']);
lesson(7,P('CTR, CPC, CVR aur CPA','CTR, CPC, CVR and CPA'),P('CTR = clicks ÷ impressions. CPC = spend ÷ clicks. Is simple Search model mein CVR = conversions ÷ clicks. CPA = spend ÷ conversions. Percentages ke liye ×100 karo.','CTR = clicks ÷ impressions. CPC = spend ÷ clicks. In this simple Search model, CVR = conversions ÷ clicks. CPA = spend ÷ conversions. Multiply ratios by 100 for percentages.'),P('2,000 impressions, 100 clicks, Rs 5,000 spend aur 5 leads: CTR 5%, CPC Rs 50, CVR 5%, CPL Rs 1,000.','2,000 impressions, 100 clicks, Rs 5,000 spend and 5 leads: CTR 5%, CPC Rs 50, CVR 5%, CPL Rs 1,000.'),[P('Metrics calculator mein example solve karo.','Solve the example in the metrics calculator.'),P('Zero denominator ko zero cost na samjho; result undefined hai.','A zero denominator is not zero cost; the result is undefined.')],P('Rs 5,000 spend aur 5 leads ka CPL?','Rs 5,000 spend and 5 leads: what is CPL?'),[P('Rs 100','Rs 100'),P('Rs 1,000','Rs 1,000'),P('Rs 5,000','Rs 5,000')],1,P('5,000 ÷ 5 = 1,000. Har metric ka denominator samjho.','5,000 ÷ 5 = 1,000. Always identify the denominator.'),[],'calculator');
lesson(7,P('ROAS, margin aur break-even','ROAS, margin and break-even'),P('ROAS = attributed revenue ÷ ad spend. Contribution after ads = revenue × contribution margin − ad spend. Break-even revenue ROAS = 1 ÷ margin fraction, jab relevant variable costs margin mein included hon.','ROAS = attributed revenue ÷ ad spend. Contribution after ads = revenue × contribution margin − ad spend. Break-even revenue ROAS = 1 ÷ margin fraction when relevant variable costs are included in margin.'),P('Rs 30,000 revenue, Rs 10,000 spend aur 25% margin: ROAS 3×, lekin contribution after ads −Rs 2,500.','Rs 30,000 revenue, Rs 10,000 spend and a 25% margin: ROAS is 3×, but contribution after ads is −Rs 2,500.'),[P('Revenue ROAS ko margin ke saath compare karo.','Compare revenue ROAS with contribution margin.'),P('Returns, taxes, delivery aur repeat revenue ke assumptions likho.','State assumptions for returns, taxes, delivery and repeat revenue.')],P('25% margin ka break-even revenue ROAS?','What is break-even revenue ROAS at a 25% margin?'),[P('4× / 400%','4× / 400%'),P('0.25× / 25%','0.25× / 25%')],0,P('1 ÷ 0.25 = 4. Ye simplified break-even hai; fixed overhead abhi subtract nahi hua.','1 ÷ 0.25 = 4. This simplified break-even excludes fixed overhead.'),[],'calculator');
lesson(7,P('Forecast: andaza, promise nahi','Forecasts are estimates'),P('Estimated clicks = budget ÷ CPC; leads = clicks × conversion rate; customers = leads × close rate. Fractional customers expected averages hain, guaranteed real people nahi.','Estimated clicks = budget ÷ CPC; leads = clicks × conversion rate; customers = leads × close rate. Fractional customers are expected averages, not guaranteed people.'),P('Rs 10,000 budget, Rs 100 CPC, 10% CVR aur 20% close rate se 100 clicks, 10 leads aur 2 expected customers.','A Rs 10,000 budget, Rs 100 CPC, 10% CVR and 20% close rate imply 100 clicks, 10 leads and 2 expected customers.'),[P('Forecast mein weak, base aur strong assumptions try karo.','Try weak, base and strong assumptions in the forecast.'),P('Max affordable CPC ≈ target CPL × click-to-lead CVR calculate karo.','Estimate max affordable CPC ≈ target CPL × click-to-lead CVR.')],P('Forecast mein 2 customers aaye: guaranteed?','A forecast predicts 2 customers: guaranteed?'),[P('Haan','Yes'),P('Nahi, assumptions ka estimate','No, it is an assumption-based estimate')],1,P('Real demand, auctions aur execution results badal saktay hain.','Real demand, auctions and execution can change results.'),[],'calculator');
lesson(8,P('Launch se pehle checklist','The pre-launch checklist'),P('Spend se pehle measurement, targeting, copy, page aur budget verify karo. Learning app mein launch simulated hai; real Google account mein koi change nahi hota.','Before spending, verify measurement, targeting, copy, destination and budget. Launching here is simulated; this app does not change a real Google Ads account.'),P('Broken form ke saath perfect ad bhi leads miss kar sakta hai. Test submission ko CRM tak follow karo.','Even a strong ad can lose leads through a broken form. Follow a test submission into the CRM.'),[P('Campaign builder ke required fields complete karo.','Complete required fields in the campaign builder.'),P('Launch checklist mein har item khud verify karo.','Verify every item in the launch checklist.'),P('Draft export karo aur actual account mein review ke baad implement karo.','Export the draft and review it before implementing in a real account.')],P('Is app ka launch button real spend start karta hai?','Does this app’s launch button start real spending?'),[P('Nahi, sirf simulation','No, it is a simulation'),P('Haan','Yes')],0,P('Practice safe hai; real account implementation separate action hai.','Practice is separate from implementation in a real ad account.'),['setup'],'campaign');
lesson(8,P('Reports aur impression share','Reports and impression share'),P('Date range, goal aur conversion lag samajh kar report parho. Search terms, network, device, location, time aur landing-page segments diagnose karne mein help karte hain. Impression share eligible opportunity ka measure hai.','Read reports with date range, goals and conversion lag in mind. Query, network, device, location, time and page segments aid diagnosis. Impression share measures eligible opportunity.'),P('Lost share due to budget aur rank alag signals hain. Har lost impression ko buy karna profitable nahi hota.','Lost share from budget and rank are different signals. Buying every missed impression is not necessarily profitable.'),[P('Same mature date range par comparison karo.','Compare the same mature date ranges.'),P('Auction Insights ko competition signal samjho, competitor profit report nahi.','Treat Auction Insights as a competition signal, not a competitor profit report.'),P('Change history ke saath spikes/drops investigate karo.','Investigate spikes and drops alongside change history.')],P('100% impression share hamesha best business goal?','Is 100% impression share always the best business goal?'),[P('Nahi; profitable demand aur objective dekho','No; consider profitable demand and objectives'),P('Haan, har business ke liye','Yes, for every business')],0,P('Visibility aur profitability ko alag evaluate karo.','Evaluate visibility and profitability separately.'),['terms','rank']);
lesson(8,P('Attribution aur conversion delay','Attribution and conversion delay'),P('Customer aaj click aur baad mein buy kar sakta hai. Attribution credit assign karta hai; conversion window decide karti hai kitni der baad action count ho sakta hai. Platform credit incrementality ka proof nahi.','A customer may click today and buy later. Attribution assigns credit; the conversion window determines how long an action may qualify. Platform attribution does not prove incrementality.'),P('B2B sales ko 3 haftay lagtay hon to kal ke CPA par final judgment incomplete hai.','If B2B sales take three weeks, judging yesterday’s final CPA is premature.'),[P('Conversion window buying cycle ke mutabiq review karo.','Review conversion windows against the buying cycle.'),P('Ads, GA4 aur CRM mein timezone, attribution aur count rules compare karo.','Compare timezones, attribution and counting rules across Ads, GA4 and CRM.')],P('Aaj ke clicks ka complete sales result aaj hi milta hai?','Do today’s clicks always have complete sales results today?'),[P('Haan','Yes'),P('Nahi, conversion delay ho sakta hai','No, conversion delay can apply')],1,P('Recent periods incomplete ho saktay hain; mature cohorts compare karo.','Recent periods may be incomplete; compare mature cohorts.'),['window']);
lesson(9,P('Optimization ka order','An optimization order'),P('Pehle data ki sachai, phir relevance, phir page/offer aur phir bidding/budget constraints inspect karo. Priority expected impact aur evidence se decide karo, random daily edits se nahi.','Inspect measurement first, then relevance, then the page/offer and bidding/budget constraints. Prioritize expected impact and evidence rather than random daily edits.'),P('Tracking broken ho to automated bidding ka target change karne se root problem solve nahi hota.','Changing an automated bidding target does not fix broken tracking.'),[P('Ek bottleneck aur uski evidence likho.','Write one bottleneck and the evidence for it.'),P('Ek focused change, expected effect aur review date note karo.','Record one focused change, its expected effect and a review date.')],P('Pehle kya fix hoga: duplicate conversion ya headline punctuation?','What should be fixed first: duplicate conversions or headline punctuation?'),[P('Duplicate conversion','Duplicate conversions'),P('Punctuation','Punctuation')],0,P('Measurement errors decisions aur optimization dono mislead karte hain.','Measurement errors mislead both decisions and optimization.'),['tracking','terms'],'diagnose');
lesson(9,P('Experiments: fair comparison','Experiments and fair comparisons'),P('Hypothesis likho, success metric aur guardrails choose karo, phir controlled test karo. Before/after comparison seasonality aur competition se confuse ho sakta hai. Chhota sample certainty nahi deta.','Write a hypothesis, choose success metrics and guardrails, then run a controlled test. Before/after comparisons can be confounded by seasonality and competition. Small samples do not provide certainty.'),P('“New landing page qualified lead rate improve karega” testable hai. Saath bids, keywords aur offer badal dogay to result samajhna mushkil hai.','“The new page will improve qualified-lead rate” is testable. Changing bids, keywords and the offer too makes interpretation harder.'),[P('Control aur trial ka sirf planned difference define karo.','Define the planned difference between control and trial.'),P('Duration ko demand, sample aur sales delay se decide karo.','Choose duration around demand, sample size and sales delay.'),P('Result inconclusive ho to honestly record karo.','Record inconclusive results honestly.')],P('2 conversions vs 1 conversion: winner proven?','Two conversions versus one: is the winner proven?'),[P('Haan','Yes'),P('Nahi, sample aur uncertainty dekho','No, inspect sample size and uncertainty')],1,P('Random variation ko business insight mat samjho.','Do not mistake random variation for a business insight.'),['experiment']);
lesson(9,P('Scaling aur diminishing returns','Scaling and diminishing returns'),P('Achha historical CPA har extra rupee par repeat nahi hota. Zyada budget ka result remaining demand, auction cost, targets aur sales capacity par depend karta hai.','A good historical CPA may not repeat for every extra rupee. Additional budget depends on remaining demand, auction cost, targets and sales capacity.'),P('Team 10 bookings handle karti hai; 30 bookings la kar bhi lost calls aur bad service ho sakti hai.','If the team can handle ten bookings, generating thirty may cause missed calls and poor service.'),[P('Profitable mature results aur capacity validate karo.','Validate mature profitable results and service capacity.'),P('Controlled budget change aur marginal outcome measure karo.','Make a controlled budget change and measure marginal outcomes.'),P('Universal fixed percentage rule ke bajaye context document karo.','Document context rather than following a universal fixed-percentage rule.')],P('Budget double karne se profit double guaranteed?','Does doubling budget guarantee double profit?'),[P('Nahi','No'),P('Haan','Yes')],0,P('Incremental results aur contribution after ads track karo.','Track incremental results and contribution after ads.'),['budget','bid'],'calculator');
lesson(10,P('Impressions ya clicks nahi aa rahay','No impressions or clicks'),P('Account billing, verification, eligibility, ad status, dates, schedule, location, keyword volume, negatives, budget aur bid constraints ko systematic order mein inspect karo.','Inspect billing, verification, eligibility, ad status, dates, schedule, location, keyword volume, negatives, budget and bid constraints systematically.'),P('Negative “repair” useful repair keywords ko block kar sakta hai. Bid barhana is conflict ka solution nahi.','A negative “repair” can block useful repair keywords. Increasing bids does not resolve the conflict.'),[P('Account aur campaign status se shuru karo.','Start with account and campaign status.'),P('Ad Preview/Diagnosis aur exact status reasons use karo.','Use Ad Preview/Diagnosis and exact status reasons.'),P('Apne ads baar baar Google par search/click mat karo.','Avoid repeatedly searching for or clicking your own ads.')],P('No impressions par pehle budget double?','No impressions: double budget first?'),[P('Nahi, eligibility aur constraints diagnose karo','No, diagnose eligibility and constraints'),P('Haan','Yes')],0,P('Problem ka reason identify karo, phir relevant fix choose karo.','Identify the cause before choosing the fix.'),['setup','negative'],'diagnose');
lesson(10,P('Clicks hain, conversions nahi','Clicks without conversions'),P('Pehle real submissions aur tracking compare karo. Phir intent, page functionality, speed, offer, device experience aur sales response dekho. Har zero conversion keyword foran waste nahi.','Compare real submissions with tracking first. Then inspect intent, page function, speed, offer, device experience and sales response. A zero-conversion keyword is not automatically waste.'),P('3 clicks aur 0 leads se final decision weak hai. Bohat irrelevant query ko zero leads ka wait kiye baghair block kiya ja sakta hai.','Three clicks and no leads provide weak performance evidence. Clearly irrelevant queries can be excluded without waiting for lead data.'),[P('Ek real conversion end-to-end test karo.','Test a real conversion end to end.'),P('Mature relevant traffic ko sample aur business risk ke context mein evaluate karo.','Evaluate mature relevant traffic against sample size and business risk.')],P('100 backend orders aur Ads mein 0 conversions: pehla suspicion?','100 backend orders but 0 Ads conversions: first suspicion?'),[P('Measurement ya attribution issue','A measurement or attribution issue'),P('Product ki demand zero','Zero product demand')],0,P('Numbers reconcile karo; tracking aur attribution route verify karo.','Reconcile numbers and verify tracking and attribution.'),['tracking','window'],'diagnose');
lesson(10,P('Mehngi ya low-quality leads','Expensive or low-quality leads'),P('CPA = CPC ÷ CVR is simple click-based funnel mein. High CPA ka reason expensive clicks, weak conversion ya dono ho saktay hain. Low CPL ke bawajood poor qualification bhi problem hai.','In a simple click-based funnel, CPA = CPC ÷ CVR. High CPA can come from expensive clicks, low conversion rate or both. Low CPL can still hide poor qualification.'),P('Rs 100 CPC aur 2% CVR se CPA Rs 5,000. CVR 4% ho to same CPC par Rs 2,500. Ye model hai, guaranteed uplift nahi.','Rs 100 CPC at 2% CVR yields Rs 5,000 CPA. At 4% CVR it yields Rs 2,500. This is a model, not a guaranteed improvement.'),[P('CPC, CVR, qualification rate aur close rate alag dekho.','Inspect CPC, CVR, qualification rate and close rate separately.'),P('Spam, irrelevant areas aur unanswerable calls audit karo.','Audit spam, irrelevant areas and unanswered calls.')],P('Cheap lead ka matlab valuable customer?','Does a cheap lead mean a valuable customer?'),[P('Haan','Yes'),P('Nahi, qualification aur sales dekho','No, inspect qualification and sales')],1,P('Qualified CPA aur actual contribution report karo.','Report qualified CPA and actual contribution.'),['offline'],'diagnose');
lesson(11,P('AI Max: features aur control','AI Max: features and controls'),P('AI Max Search ke andar targeting aur creative enhancements ka suite hai. Search-term matching, text customization aur final URL expansion ko samjho. Ye Performance Max se alag hai.','AI Max is a suite of targeting and creative enhancements inside Search. Understand search-term matching, text customization and final URL expansion. It differs from Performance Max.'),P('URL expansion relevant alternate page choose kar sakta hai; unwanted pages exclude karo. Final URL expansion on ho to RSA pinning respect nahi hoti.','URL expansion can select an alternative relevant page; exclude unsuitable pages. RSA pinning is not respected when final URL expansion is enabled.'),[P('Brand, URL aur location controls review karo.','Review brand, URL and location controls.'),P('Generated copy aur selected landing pages inspect karo.','Inspect generated copy and selected landing pages.'),P('Reliable outcomes aur guardrails ke saath experiment consider karo.','Consider an experiment with reliable outcomes and guardrails.')],P('AI Max aur Performance Max same hain?','Are AI Max and Performance Max the same?'),[P('Nahi, AI Max Search ke andar features hain','No, AI Max adds features within Search'),P('Haan','Yes')],0,P('Automation ke controls aur actual outcomes dono inspect karo.','Inspect both automation controls and actual outcomes.'),['ai','aicontrol'],'media');
lesson(11,P('DSA, broad aur expansion','DSA, broad and expansion'),P('Dynamic Search Ads website content se matching aur headlines mein help karte hain. Coverage, page quality aur exclusions matter kartay hain. Feature lifecycle aur account availability implementation se pehle verify karo.','Dynamic Search Ads use website content to support matching and headlines. Coverage, page quality and exclusions matter. Verify lifecycle and account availability before implementing.'),P('Google ke current notice mein DSA campaigns ki February 2027 se AI Max upgrade ka zikr hai; abhi ke setup ko future-proof review karo.','A current Google notice describes DSA upgrades to AI Max starting February 2027; review future implications for your setup.'),[P('Search-term aur landing-page reports inspect karo.','Inspect search-term and landing-page reports.'),P('Login, careers aur irrelevant pages exclude karne ka plan banao.','Plan exclusions for login, careers and irrelevant pages.')],P('Poor website content ke saath unlimited expansion best idea?','Is unlimited expansion on a poor website a sound plan?'),[P('Nahi, page quality aur controls pehle','No, address page quality and controls first'),P('Haan','Yes')],0,P('Automation website aur measurement inputs ki quality par depend karti hai.','Automation depends on the quality of site and measurement inputs.'),['dsa','aicontrol']);
lesson(11,P('Advanced tools aur exploration','Advanced tools and exploration'),P('Editor bulk changes, scripts checks/automation aur APIs integrations mein help karte hain. Preview, logs, permissions aur rollback rakho. Smart Bidding Exploration expansion ka advanced option hai; eligibility aur ROAS flexibility check karo.','Editor supports bulk changes, scripts support checks/automation, and APIs support integrations. Use previews, logs, permissions and rollback plans. Smart Bidding Exploration is an advanced expansion option; check eligibility and ROAS flexibility.'),P('Script se sab low-score keywords pause karna weak rule hai. Pehle report-only output review karo.','Automatically pausing every low-score keyword is a weak rule. Review report-only output first.'),[P('Bulk changes ka backup/export lo.','Export a backup before bulk changes.'),P('Script ko small scope aur logs ke saath test karo.','Test scripts with limited scope and logs.'),P('Budget-constrained campaigns mein expansion ki suitability evaluate karo.','Evaluate expansion carefully for budget-constrained campaigns.')],P('Naya automation seedha full account par run?','Run new automation across the entire account immediately?'),[P('Nahi, preview aur small-scope test karo','No, preview and test a small scope'),P('Haan','Yes')],0,P('Automation ka scale mistakes ko bhi scale kar sakta hai.','Automation can scale mistakes as well as useful work.'),['explore']);
lesson(12,P('Access, billing aur verification','Access, billing and verification'),P('Business ownership, user access, billing responsibility, advertiser verification aur account currency/timezone document karo. Minimum required access do; passwords share karne ke bajaye invited users use karo.','Document business ownership, access, billing responsibility, advertiser verification and account currency/timezone. Grant only needed access and invite users rather than sharing passwords.'),P('Agency ko access chahiye, business ko ownership aur billing visibility retain karni chahiye.','An agency may need access while the business retains ownership and billing visibility.'),[P('Owner, admin aur day-to-day operator identify karo.','Identify the owner, admins and day-to-day operator.'),P('Payment alerts aur verification requests check karo.','Check payment alerts and verification requests.')],P('Freelancer ko apna password bhejna best process?','Is sending a freelancer your password the best process?'),[P('Nahi; supported access invite use karo','No; use supported access invitations'),P('Haan','Yes')],0,P('Access ko roles aur business ownership ke saath manage karo.','Manage access around roles and business ownership.'),['setup']);
lesson(12,P('Daily, weekly aur monthly routine','Daily, weekly and monthly routines'),P('Daily critical failures aur spend anomalies dekho; weekly intent, lead quality aur mature results; monthly economics, experiments aur strategy review karo. Cadence account size aur risk ke hisaab se badalti hai.','Check critical failures and spend anomalies daily; inspect intent, lead quality and mature results weekly; review economics, experiments and strategy monthly. Adjust cadence to account size and risk.'),P('Daily har setting edit karna management nahi. Useful checks bina unnecessary changes bhi ho saktay hain.','Editing every setting daily is not a management strategy. Useful checks do not always require changes.'),[P('Launch checklist aur recurring review list save karo.','Save launch and recurring review checklists.'),P('Har meaningful change ka reason aur review date log karo.','Log reasons and review dates for meaningful changes.')],P('Aaj koi edit nahi ki: kya management fail ho gayi?','No edits today: has management failed?'),[P('Haan','Yes'),P('Nahi, evidence par action lo','No, act when evidence supports it')],1,P('Activity se zyada decision quality matter karti hai.','Decision quality matters more than activity.'),['terms','bid'],'checklist');
lesson(12,P('Honest reporting aur limitations','Honest reporting and limitations'),P('Spend, outcomes, quality, revenue, contribution aur uncertainty saath report karo. Search terms mein privacy thresholds ki wajah se complete query list nahi milti. Recommendations ko review karo; automatic acceptance success guarantee nahi.','Report spend, outcomes, quality, revenue, contribution and uncertainty together. Privacy thresholds mean search-term reports are not complete query logs. Review recommendations; automatic acceptance does not guarantee success.'),P('“100 leads” ke saath qualified leads, duplicates aur closed sales batao. Client ko sirf vanity metrics na do.','Alongside “100 leads,” disclose qualified leads, duplicates and sales. Avoid reporting only vanity metrics.'),[P('One-page report mein result, reason, action aur risk likho.','Write a one-page report with results, explanations, actions and risks.'),P('Attributed sales aur incremental sales ka difference mention karo.','Distinguish attributed sales from incremental sales.')],P('Search-term report har query dikhata hai?','Does the search-term report show every query?'),[P('Nahi, reporting thresholds apply hotay hain','No, reporting thresholds apply'),P('Haan','Yes')],0,P('Visible rows ko complete traffic log na samjho.','Do not treat visible rows as a complete traffic log.'),['terms']);
lesson(13,P('Teen businesses, teen strategies','Three businesses, three strategies'),P('Local service ko relevant area aur answered enquiries chahiye. Ecommerce ko purchases, margins aur returns. B2B ko qualification, longer sales delay aur CRM feedback. Ek universal campaign recipe nahi.','A local service needs serviceable locations and answered enquiries. Ecommerce needs purchases, margins and returns. B2B needs qualification, longer sales cycles and CRM feedback. There is no universal recipe.'),P('Business selector se AC repair, shoe store aur accounting service switch karo. Calculator defaults aur keyword exercises change hotay hain.','Switch between AC repair, shoes and accounting. Calculator defaults and keyword exercises change.'),[P('Teenon businesses ke break-even numbers compare karo.','Compare break-even numbers for all three businesses.'),P('Har business ka main conversion aur sales delay describe karo.','Describe the main conversion and sales delay for each business.')],P('Ecommerce aur B2B ke same CPA target lazmi?','Must ecommerce and B2B share the same CPA target?'),[P('Nahi; economics aur outcomes alag hain','No; economics and outcomes differ'),P('Haan','Yes')],0,P('Targets business model aur measured outcomes se aatay hain.','Targets follow the business model and measured outcomes.'),[],'calculator');
lesson(13,P('Account audit: root cause pehchano','Audit the root cause'),P('Audit mein measurement, structure, intent, copy, pages, bidding, budgets, goals aur policy status systematically review karo. Har issue ko evidence, impact aur suggested action do.','Audit measurement, structure, intent, copy, pages, bidding, budgets, goals and policy status systematically. Record evidence, impact and a proposed action for each issue.'),P('Low CTR aur poor sales dono hon to sirf headlines ko blame na karo; query intent aur offer bhi inspect karo.','With low CTR and poor sales, do not blame headlines alone; inspect query intent and the offer.'),[P('Diagnosis lab ke har case ko solve karo.','Solve every case in the diagnosis lab.'),P('Top three fixes ko business impact ke mutabiq order karo.','Rank the top three fixes by business impact.')],P('Audit recommendation ka strong format?','What makes a strong audit recommendation?'),[P('Evidence → likely cause → action → validation','Evidence → likely cause → action → validation'),P('Mujhe ye setting pasand nahi','I dislike this setting')],0,P('Confidence aur alternative explanations bhi record karo.','Record confidence and alternative explanations too.'),['tracking','terms'],'diagnose');
lesson(13,P('Final challenge: apna plan defend karo','Final challenge: defend your plan'),P('Readiness ka matlab sirf quiz pass nahi. Business goal explain karo, tracking plan banao, intent select karo, relevant ad likho, economics solve karo aur optimization decision defend karo.','Readiness is more than a quiz pass. Explain the business goal, design measurement, choose intent, write a relevant ad, solve economics and defend an optimization decision.'),P('Apna campaign draft, calculator assumptions aur launch checklist export karo. Ye reviewable plan hai; live performance ka proof nahi.','Export your campaign draft, calculator assumptions and launch checklist. This is a reviewable plan, not proof of live performance.'),[P('Campaign lab mein complete draft aur validation results lo.','Create a complete draft and validation results in the campaign lab.'),P('Progress page se assessment dekho aur weak topics revisit karo.','Review the assessment on the progress page and revisit weak topics.'),P('Real implementation mein supervised tracking test aur controlled budget se start karo.','For real implementation, use a supervised tracking test and a controlled budget.')],P('Course finish honay ka honest matlab?','What does course completion honestly mean?'),[P('Har campaign profit guarantee','Guaranteed profit on every campaign'),P('Practice complete; real execution aur judgment abhi bhi matter kartay hain','Practice completed; real execution and judgment still matter')],1,P('Learning ko real-world feedback se continue karo. Mastery ek badge se prove nahi hoti.','Continue learning through real-world feedback. A badge does not prove mastery.'),[],'campaign');
const GLOSSARY=[
 ['Impression','Ad ka ek baar show hona.','One instance of an ad being shown.'],['Click','User ka ad par click.','A user click on an ad.'],['CTR','Impressions mein se kitnay clicks banay.','Clicks as a share of impressions.'],['CPC','Har click ki average cost.','Average cost per click.'],['Conversion','Defined meaningful action, jaise valid lead ya purchase.','A defined meaningful action, such as a valid lead or purchase.'],['CVR','Eligible interactions mein se conversion ka rate.','Conversion rate among eligible interactions.'],['CPA / CPL','Har conversion / lead ki average ad cost.','Average ad cost per conversion / lead.'],['ROAS','Attributed revenue ya value ÷ ad spend; profit nahi.','Attributed revenue or value divided by ad spend; not profit.'],['Keyword','Advertiser ka search targeting input.','An advertiser input for search targeting.'],['Search term','User ki actual search query.','The user’s actual search query.'],['Negative keyword','Unwanted searches exclude karne ka input.','An input used to exclude unwanted searches.'],['Ad group','Related keywords aur ads ka group.','A group of related keywords and ads.'],['RSA','Responsive Search Ad; text assets ko combine karta hai.','Responsive Search Ad; assembles text assets.'],['Landing page','Click ke baad khulnay wala page.','The page opened after an ad click.'],['Quality Score','1–10 keyword diagnostic, direct auction input nahi.','A 1–10 keyword diagnostic, not a direct auction input.'],['Ad Rank','Auction mein eligibility aur position determine karne wali values.','Values determining auction eligibility and placement.'],['Primary conversion','Selected goal ke saath bidding mein use honay wala action.','An action usable for bidding when its goal is selected.'],['Secondary conversion','Aam tor par observation; custom goal exception hai.','Usually observation-only; custom goals are an exception.'],['Attribution','Marketing interactions ko outcome ka credit dena.','Assigning outcome credit to marketing interactions.'],['Conversion lag','Interaction aur reported conversion ke darmiyan delay.','Delay between an interaction and reported conversion.'],['Contribution margin','Relevant variable costs ke baad revenue ka bacha hua hissa.','Revenue remaining after relevant variable costs.'],['Close rate','Leads mein se customers ka proportion.','The proportion of leads becoming customers.'],['AI Max','Search targeting aur creative enhancements ka suite.','A suite of Search targeting and creative enhancements.'],['Smart Bidding','Auction-time conversion/value optimization.','Auction-time conversion/value optimization.'],['UTM','Analytics campaign reporting ke URL parameters.','URL parameters for analytics campaign reporting.'],['GCLID','Google click identifier; applicable attribution/import flows mein use hota hai.','Google click identifier used in applicable attribution/import flows.'],['Observation','Audience reporting mode jo aam tor par reach narrow nahi karta.','Audience reporting mode that generally does not narrow reach.'],['Incrementality','Ads ki wajah se extra result, jo warna na hota.','Additional outcomes caused by ads that would not otherwise occur.']
];
const LAUNCH_CHECKS=[P('Correct business, goal, currency aur timezone review kiye','Reviewed business, goal, currency and timezone'),P('Test conversion backend/CRM tak verify ki','Verified a test conversion through to the backend/CRM'),P('Primary goals aur duplicate counting check ki','Checked primary goals and duplicate counting'),P('Location, languages, networks aur schedule check kiye','Checked locations, languages, networks and schedule'),P('Keywords, negatives aur conflicts review kiye','Reviewed keywords, negatives and conflicts'),P('Copy, assets aur real offer consistent hain','Copy, assets and the real offer are consistent'),P('Mobile landing page, form aur phone test kiye','Tested mobile page, form and phone'),P('Budget exposure aur bidding objective approve kiye','Reviewed budget exposure and bidding objective'),P('Policy, privacy aur applicable consent requirements review kiye','Reviewed policy, privacy and applicable consent requirements'),P('Sales follow-up owner aur review date set ki','Assigned sales follow-up ownership and a review date')];
